function collectActiveUsers(users, cutoff) {
  const activeUsers = []

  for (const user of users) {
    if (!user.isOnline || user.lastSeenAt <= cutoff) {
      continue
    }

    activeUsers.push(user.name)
  }

  return activeUsers
}

function groupPostsByTag(posts) {
  const grouped = {}

  for (const post of posts) {
    for (const tag of post.tags) {
      grouped[tag] ??= []
      grouped[tag].push(post.slug)
    }
  }

  return grouped
}

async function loadProjectSummary(fetcher, projectId) {
  const response = await fetcher(`/api/projects/${projectId}`)

  if (!response.ok) {
    throw new Error('Failed to load project summary')
  }

  const project = await response.json()
  return `${project.name}:${project.branch}`.toLowerCase()
}

function buildLeaderboard(entries) {
  return entries
    .filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score)
    .slice(0, 5)
    .map((entry, index) => ({
      rank: index + 1,
      name: entry.name,
      score: entry.score,
    }))
}

function clampScore(score, minimum, maximum) {
  if (score < minimum) {
    return minimum
  }

  if (score > maximum) {
    return maximum
  }

  return score
}

function debounce(fn, waitMs) {
  let timeoutId = null

  return function debounced(...args) {
    if (timeoutId !== null) {
      clearTimeout(timeoutId)
    }

    timeoutId = setTimeout(() => {
      timeoutId = null
      fn.apply(this, args)
    }, waitMs)
  }
}

function parseQueryString(input) {
  const params = {}
  const trimmed = input.replace(/^\?/, '')

  for (const pair of trimmed.split('&')) {
    if (!pair) continue

    const [rawKey, rawValue = ''] = pair.split('=')
    params[decodeURIComponent(rawKey)] = decodeURIComponent(rawValue)
  }

  return params
}

async function retryWithBackoff(operation, attempts = 3) {
  let lastError = null

  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await operation()
    } catch (error) {
      lastError = error
      await new Promise((resolve) => setTimeout(resolve, 2 ** attempt * 100))
    }
  }

  throw lastError
}

function chunk(items, size) {
  if (size <= 0) {
    throw new RangeError('chunk size must be positive')
  }

  const result = []

  for (let index = 0; index < items.length; index += size) {
    result.push(items.slice(index, index + size))
  }

  return result
}

function deepFreeze(target) {
  if (target === null || typeof target !== 'object') {
    return target
  }

  for (const key of Object.keys(target)) {
    deepFreeze(target[key])
  }

  return Object.freeze(target)
}
